package org.eclipse.rdf4j.federated.evaluation.iterator;

import java.util.List;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.ConvertingIteration;
import org.eclipse.rdf4j.federated.util.QueryAlgebraUtil;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet;

/**
 * Inserts original bindings into the result.
 *
 * @author Andreas Schwarte
 */
public class InsertBindingsIteration extends ConvertingIteration<BindingSet, BindingSet> {

	protected final BindingSet bindings;
	private final List<String> explicitNullNames;

	public InsertBindingsIteration(CloseableIteration<BindingSet> iter, BindingSet bindings) {
		super(iter);
		this.bindings = bindings;
		this.explicitNullNames = bindings.getBindingNames()
				.stream()
				.filter(name -> QueryAlgebraUtil.isExplicitNullBinding(bindings, name))
				.toList();
	}

	@Override
	protected BindingSet convert(BindingSet bIn) throws QueryEvaluationException {
		QueryBindingSet res = new QueryBindingSet(bindings.size() + bIn.size());
		res.addAll(bindings);
		for (String name : explicitNullNames) {
			res.removeBinding(name);
		}
		res.addAll(bIn);
		for (String name : explicitNullNames) {
			res.setBinding(name, null);
		}
		return res;
	}
}
